create type public.credit_memo_status as enum('draft','certified','superseded');create type public.credit_decision_type as enum('approved','approved_with_conditions','declined','returned');
create table public.credit_memos(id uuid primary key default gen_random_uuid(),organization_id uuid not null,deal_id uuid not null,assessment_id uuid not null,memo_version text not null check(memo_version='buddy-credit-memo.v1'),memo_json jsonb not null,content_hash text not null check(content_hash~'^[0-9a-f]{64}$'),status public.credit_memo_status not null default'draft',created_at timestamptz not null default now(),certified_at timestamptz,certified_by uuid references auth.users(id),certification_statement text,unique(id,organization_id),unique(assessment_id,content_hash),foreign key(deal_id,organization_id)references public.deals(id,organization_id),foreign key(assessment_id,organization_id)references public.credit_assessments(id,organization_id),check((status='certified' and certified_at is not null and certified_by is not null and length(trim(certification_statement))>0)or status<>'certified'));
create table public.credit_conditions(id uuid primary key default gen_random_uuid(),organization_id uuid not null,deal_id uuid not null,memo_id uuid not null,description text not null,owner_user_id uuid not null references auth.users(id),due_at timestamptz,status text not null default'open' check(status in('open','satisfied','waived')),resolution_rationale text,created_at timestamptz not null default now(),foreign key(memo_id,organization_id)references public.credit_memos(id,organization_id),foreign key(deal_id,organization_id)references public.deals(id,organization_id));
create table public.credit_committee_votes(id uuid primary key default gen_random_uuid(),organization_id uuid not null,deal_id uuid not null,memo_id uuid not null,voter_user_id uuid not null references auth.users(id),vote text not null check(vote in('approve','decline','abstain','return')),rationale text not null check(length(trim(rationale))>0),created_at timestamptz not null default now(),foreign key(memo_id,organization_id)references public.credit_memos(id,organization_id),unique(memo_id,voter_user_id));
create table public.credit_decisions(id uuid primary key default gen_random_uuid(),organization_id uuid not null,deal_id uuid not null,memo_id uuid not null,decision public.credit_decision_type not null,rationale text not null check(length(trim(rationale))>0),approver_user_id uuid not null references auth.users(id),approver_role public.organization_role not null,decision_snapshot jsonb not null,decision_hash text not null check(decision_hash~'^[0-9a-f]{64}$'),decided_at timestamptz not null default now(),unique(deal_id,memo_id),foreign key(memo_id,organization_id)references public.credit_memos(id,organization_id),check(approver_role in('owner','administrator','underwriter')));
alter table public.credit_memos enable row level security;alter table public.credit_conditions enable row level security;alter table public.credit_committee_votes enable row level security;alter table public.credit_decisions enable row level security;revoke all on public.credit_memos,public.credit_conditions,public.credit_committee_votes,public.credit_decisions from public,anon,authenticated;grant select on public.credit_memos,public.credit_conditions,public.credit_committee_votes,public.credit_decisions to authenticated;
create policy "credit_memos_read" on public.credit_memos for select to authenticated using(exists(select 1 from public.organization_memberships m where m.organization_id=credit_memos.organization_id and m.user_id=auth.uid() and m.is_active));create policy "credit_conditions_read" on public.credit_conditions for select to authenticated using(exists(select 1 from public.organization_memberships m where m.organization_id=credit_conditions.organization_id and m.user_id=auth.uid() and m.is_active));create policy "credit_committee_votes_read" on public.credit_committee_votes for select to authenticated using(exists(select 1 from public.organization_memberships m where m.organization_id=credit_committee_votes.organization_id and m.user_id=auth.uid() and m.is_active));create policy "credit_decisions_read" on public.credit_decisions for select to authenticated using(exists(select 1 from public.organization_memberships m where m.organization_id=credit_decisions.organization_id and m.user_id=auth.uid() and m.is_active));
create function public.prevent_credit_decision_mutation()returns trigger language plpgsql set search_path='' as $$begin raise exception using errcode='55000',message='Credit decisions are immutable.';end$$;create trigger credit_decisions_immutable before update or delete on public.credit_decisions for each row execute function public.prevent_credit_decision_mutation();revoke all on function public.prevent_credit_decision_mutation() from public,anon,authenticated,service_role;comment on table public.credit_decisions is 'Immutable human credit decisions. No autonomous approval path is installed.';
